90	/* ── Data structures ────────────────────────────────────── */
91	
92	typedef struct {
93	    char name[128]; /* "server.tool" prefixed name */
94	    char description[256];
95	    char* input_schema_json; /* heap */
96	    char server_name[64]; /* which server owns this tool */
97	} mcp_remote_tool_t;
98	
99	typedef struct {
100	    char name[64];
101	    char url[256];
102	    char token[128];
103	    parsed_url_t parsed;
104	    bool initialized; /* MCP initialize handshake done */
105	    char session_id[128]; /* Mcp-Session header from server */
106	} mcp_remote_server_t;
107	
108	static mcp_remote_server_t s_servers[MCP_CLIENT_MAX_SERVERS];
109	static int s_server_count = 0;
110	
111	static mcp_remote_tool_t s_tools[MCP_CLIENT_MAX_TOOLS];
112	static int s_tool_count = 0;
113	
114	static pthread_mutex_t s_mtx = PTHREAD_MUTEX_INITIALIZER;
115	static bool s_inited = false;
116	static atomic_int s_req_id = 1;
