542	/* FIX #1: discover — lock only protects data copy, network calls outside lock */
543	
544	int mcp_client_discover(void)
545	{
546	    /* Step 1: lock, copy server list, clear old tools */
547	    pthread_mutex_lock(&s_mtx);
548	
549	    int nservers = s_server_count;
550	    if (nservers == 0) {
551	        pthread_mutex_unlock(&s_mtx);
552	        return 0;
553	    }
554	
555	    /* Stack-copy server structs so we can release the lock */
556	    mcp_remote_server_t* srv_copy = malloc(
557	        nservers * sizeof(mcp_remote_server_t));
558	    if (!srv_copy) {
559	        pthread_mutex_unlock(&s_mtx);
560	        return -1;
561	    }
562	    memcpy(srv_copy, s_servers, nservers * sizeof(mcp_remote_server_t));
563	
564	    /* Clear existing tools */
565	    for (int i = 0; i < s_tool_count; i++) {
566	        free(s_tools[i].input_schema_json);
567	        s_tools[i].input_schema_json = NULL;
568	    }
569	    s_tool_count = 0;
570	
571	    pthread_mutex_unlock(&s_mtx);
572	
573	    /* Step 2: network calls WITHOUT lock — each server gets its own
574	     * temporary tool buffer to avoid blocking other operations */
575	    mcp_remote_tool_t* tmp_tools = malloc(
576	        MCP_CLIENT_MAX_TOOLS * sizeof(mcp_remote_tool_t));
577	    if (!tmp_tools) {
578	        free(srv_copy);
579	        return -1;
580	    }
581	
582	    int total = 0;
583	    for (int i = 0; i < nservers; i++) {
584	        int remaining = MCP_CLIENT_MAX_TOOLS - total;
585	        if (remaining <= 0)
586	            break;
587	
588	        int n = discover_server_tools(&srv_copy[i],
589	            &tmp_tools[total], remaining);
590	        if (n > 0)
591	            total += n;
592	
593	        /* Sync initialized/session_id back under lock */
594	        pthread_mutex_lock(&s_mtx);
595	        for (int j = 0; j < s_server_count; j++) {
596	            if (strcmp(s_servers[j].name, srv_copy[i].name) == 0) {
597	                s_servers[j].initialized = srv_copy[i].initialized;
598	                memcpy(s_servers[j].session_id, srv_copy[i].session_id,
599	                    sizeof(s_servers[j].session_id));
600	                break;
601	            }
602	        }
603	        pthread_mutex_unlock(&s_mtx);
604	    }
605	
606	    /* Step 3: lock, merge discovered tools into global array */
607	    pthread_mutex_lock(&s_mtx);
608	
609	    for (int i = 0; i < total && s_tool_count < MCP_CLIENT_MAX_TOOLS; i++) {
610	        s_tools[s_tool_count] = tmp_tools[i];
611	        /* Ownership of input_schema_json transferred, don't free */
612	        s_tool_count++;
613	    }
614	
615	    /* Free any tools that didn't fit */
616	    for (int i = s_tool_count; i < total; i++) {
617	        free(tmp_tools[i].input_schema_json);
618	        tmp_tools[i].input_schema_json = NULL;
619	    }
620	
621	    pthread_mutex_unlock(&s_mtx);
622	
623	    free(tmp_tools);
624	    free(srv_copy);
625	    syslog(LOG_INFO, "[%s] Total remote tools: %d\n", TAG, total);
626	    return total;
627	}
628	
629	/* FIX #2: execute — lock only for lookup, network call outside lock */
630	
631	int mcp_client_execute(const char* name, const char* input_json,
632	    char* output, size_t output_size)
633	{
634	    if (!name || !output || output_size == 0)
635	        return ERROR;
636	
637	    /* Step 1: lock, find tool + server, copy what we need, unlock */
638	    pthread_mutex_lock(&s_mtx);
639	
640	    const char* srv_name = NULL;
641	    /* FIX #6: tool names are now prefixed "server.tool", but also try
642	     * unprefixed match for backward compat with tool_registry fallback */
643	    for (int i = 0; i < s_tool_count; i++) {
644	        if (strcmp(s_tools[i].name, name) == 0) {
645	            srv_name = s_tools[i].server_name;
646	            break;
647	        }
648	    }
649	
650	    if (!srv_name) {
651	        pthread_mutex_unlock(&s_mtx);
652	        return ERROR;
653	    }
654	
655	    /* Copy server struct so we can release lock before network call */
656	    mcp_remote_server_t srv_local;
657	    bool found = false;
658	    for (int i = 0; i < s_server_count; i++) {
659	        if (strcmp(s_servers[i].name, srv_name) == 0) {
660	            srv_local = s_servers[i];
661	            found = true;
662	            break;
663	        }
664	    }
665	
666	    pthread_mutex_unlock(&s_mtx);
667	
668	    if (!found)
669	        return ERROR;
670	
671	    /* Step 2: build request and do network call WITHOUT lock */
672	
673	    /* Extract the original tool name (strip server prefix for remote call) */
674	    const char* dot = strchr(name, '.');
675	    const char* remote_name = dot ? dot + 1 : name;
676	
677	    cJSON* params = cJSON_CreateObject();
678	    if (!params)
679	        return ERROR;
680	
681	    cJSON_AddStringToObject(params, "name", remote_name);
682	    cJSON* args = cJSON_Parse(input_json ? input_json : "{}");
683	    if (!args) {
684	        args = cJSON_CreateObject();
685	        if (!args) {
686	            cJSON_Delete(params);
687	            return ERROR;
688	        }
689	    }
690	    cJSON_AddItemToObject(params, "arguments", args);
691	
692	    /* build_jsonrpc_request takes ownership of params (frees on failure) */
693	    char* body = build_jsonrpc_request("tools/call", params);
694	    if (!body)
695	        return ERROR;
696	
697	    char* resp_buf = malloc(MCP_RESP_BUF_SIZE);
698	    if (!resp_buf) {
699	        free(body);
700	        return ERROR;
701	    }
702	    resp_buf[0] = '\0';
703	
704	    int status = mcp_http_post(&srv_local, body, resp_buf, MCP_RESP_BUF_SIZE);
705	    free(body);
706	
707	    if (status < 200 || status >= 300) {
708	        snprintf(output, output_size,
709	            "{\"error\":\"MCP remote call failed: HTTP %d\"}", status);
710	        free(resp_buf);
711	        return ERROR;
712	    }
713	
714	    /* Parse result -> content[0] -> text */
715	    cJSON* result = parse_jsonrpc_result(resp_buf);
716	    free(resp_buf);
717	
718	    if (!result) {
719	        snprintf(output, output_size,
720	            "{\"error\":\"MCP remote: bad response\"}");
721	        return ERROR;
722	    }
723	
724	    cJSON* content = cJSON_GetObjectItem(result, "content");
725	    if (content && cJSON_IsArray(content)) {
726	        cJSON* first = cJSON_GetArrayItem(content, 0);
727	        if (first) {
728	            cJSON* text = cJSON_GetObjectItem(first, "text");
729	            if (text && cJSON_IsString(text)) {
730	                strncpy(output, text->valuestring, output_size - 1);
731	                output[output_size - 1] = '\0';
732	                cJSON_Delete(result);
733	                return OK;
734	            }
735	        }
736	    }
737	
738	    /* Fallback: stringify the whole result */
739	    char* fallback = cJSON_PrintUnformatted(result);
740	    if (fallback) {
741	        strncpy(output, fallback, output_size - 1);
742	        output[output_size - 1] = '\0';
743	        free(fallback);
744	    }
745	
746	    cJSON_Delete(result);
747	    return OK;
748	}
