                cJSON_AddItemToObject(t, "input_schema", empty);
            }
        }

        cJSON_AddItemToArray(arr, t);
    }

    pthread_mutex_unlock(&s_mtx);

    char* json = cJSON_PrintUnformatted(arr);
    cJSON_Delete(arr);
    return json;
