159	static conn_slot_t* pool_acquire(const char* host, const char* port)
160	{
161	    pthread_mutex_lock(&s_pool_lock);
162	
163	    /* 1. Find an existing valid slot for this host:port */
164	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
165	        conn_slot_t* s = &s_pool[i];
166	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
167	            s->in_use = true;
168	            pthread_mutex_unlock(&s_pool_lock);
169	            return s;
170	        }
171	    }
172	
173	    /* 2. Find an empty slot */
174	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
175	        if (!s_pool[i].valid && !s_pool[i].in_use) {
176	            s_pool[i].in_use = true;
177	            pthread_mutex_unlock(&s_pool_lock);
178	            return &s_pool[i];
179	        }
180	    }
181	
182	    /* 3. Evict the first non-in-use slot */
183	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
184	        if (!s_pool[i].in_use) {
185	            tls_ctx_free(&s_pool[i].ctx);
186	            s_pool[i].valid = false;
187	            s_pool[i].in_use = true;
188	            pthread_mutex_unlock(&s_pool_lock);
189	            return &s_pool[i];
190	        }
191	    }
192	
193	    pthread_mutex_unlock(&s_pool_lock);
194	    return NULL; /* all slots busy — caller falls back to ephemeral */
195	}
