197	/* Return a slot to the pool.  keep=true means the connection is still alive. */
198	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
199	{
200	    pthread_mutex_lock(&s_pool_lock);
201	    if (keep) {
202	        strncpy(s->host, host, sizeof(s->host) - 1);
203	        strncpy(s->port, port, sizeof(s->port) - 1);
204	        s->valid = true;
205	    } else {
206	        tls_ctx_free(&s->ctx);
207	        s->valid = false;
208	        s->host[0] = '\0';
209	    }
210	    s->in_use = false;
211	    pthread_mutex_unlock(&s_pool_lock);
212	}
